//[[main.tf]]
# ارائه دهنده AWS را پیکربندی کنید
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.0"
    }
  }
}

# ارائه دهنده AWS را پیکربندی کنید
provider "aws" {
  region = "us-east-1"  # منطقه دلخواه خود را جایگزین کنید
}

# یک نمونه EC2 ایجاد کنید
resource "aws_instance" "example" {
  ami           = "ami-0c55b3eb09c3757f5"  # یک AMI معتبر را برای منطقه خود جایگزین کنید
  instance_type = "t2.micro"
  tags = {
    Name = "terraform-example"
  }
}

output "instance_public_ip" {
  value = aws_instance.example.public_ip
}
